/**
 * Ready-made theme palettes an admin can start from (Features → Custom Theme → Theme Preset).
 * Each JSON file has the Import/Export format: the full palette plus its `mode`.
 * Generated by EliteaUI/local_features/custom-themes/generateCustomThemes.mjs, copy them here after regenerating.
 */
import amberShadowDark from './presets/amber-shadow-dark.json';
import arcticGlowLight from './presets/arctic-glow-light.json';
import berryBlushLight from './presets/berry-blush-light.json';
import emeraldNightDark from './presets/emerald-night-dark.json';
import midnightBlueDark from './presets/midnight-blue-dark.json';
import purpleEclipseDark from './presets/purple-eclipse-dark.json';
import quantumPinkDark from './presets/quantum-pink-dark.json';
import solarCanvasLight from './presets/solar-canvas-light.json';
import violetWhisperLight from './presets/violet-whisper-light.json';
import warmGardenLight from './presets/warm-garden-light.json';

/** Palette paths shown as swatches next to the preset name: sidebar, page background, primary */
export const PRESET_SWATCH_PATHS = [
  'components.sidebar.background',
  'background.default.primary',
  'primary.main',
];

const createPreset = (id, name, json) => {
  const { mode, ...palette } = json;
  return { id, name, mode, palette };
};

export const THEME_PRESETS = [
  createPreset('midnight-blue-dark', 'Midnight Blue', midnightBlueDark),
  createPreset('emerald-night-dark', 'Emerald Night', emeraldNightDark),
  createPreset('purple-eclipse-dark', 'Purple Eclipse', purpleEclipseDark),
  createPreset('amber-shadow-dark', 'Amber Shadow', amberShadowDark),
  createPreset('quantum-pink-dark', 'Quantum Pink', quantumPinkDark),
  createPreset('arctic-glow-light', 'Arctic Glow', arcticGlowLight),
  createPreset('berry-blush-light', 'Berry Blush', berryBlushLight),
  createPreset('solar-canvas-light', 'Solar Canvas', solarCanvasLight),
  createPreset('violet-whisper-light', 'Violet Whisper', violetWhisperLight),
  createPreset('warm-garden-light', 'Warm Garden', warmGardenLight),
];
